sys_script_include.script:
var TaskUtils = Class.create();
TaskUtils.prototype = {
    initialize: function () {
    },

    // 1. Fetch all tasks for a specific event
    fetchTasksByEvent: function (eventID) {
        var gr = new GlideRecord('x_1790116_event_ma_task');
        gr.addQuery('u_event_id.number', eventID);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push(gr.number + ' | ' + gr.u_task_name + ' | ' + gr.u_due_date);
        }
        return result.length ? result.join('\n') : 'No tasks found for this event';
    },

    // 2. Check if a task is overdue
    isTaskOverdue: function (taskID) {
        var gr = new GlideRecord('x_1790116_event_ma_task');
        gr.addQuery('number', taskID);
        gr.query();
        if (gr.next()) {
            var dueDate = new GlideDateTime(gr.u_due_date);
            var now = new GlideDateTime();
            if (dueDate.before(now) && gr.u_status != 'Completed') {
                return 'Task is overdue';
            }
            return 'Task is not overdue';
        }
        return 'Task not found';
    },

    // 3. Fetch task details by ID
    getTaskByID: function (taskID) {
        var gr = new GlideRecord('x_1790116_event_ma_task');
        gr.addQuery('number', taskID);
        gr.query();
        if (gr.next()) {
            return gr.u_task_name + ' | ' + gr.u_due_date + ' | ' + gr.u_status;
        }
        return 'Task not found';
    },

    // 4. Fetch tasks by due date
    fetchTasksByDueDate: function (dueDateStr) {
        var gr = new GlideRecord('x_1790116_event_ma_task');
        gr.addQuery('u_due_date', dueDateStr);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push(gr.number + ' | ' + gr.u_task_name + ' | ' + gr.u_status);
        }
        return result.length ? result.join('\n') : 'No tasks found for this due date';
    },

    type: 'TaskUtils'
};
